{
  "name": "MPB连续波激光器",
  "name_en": "MPB Continuous-Wave Laser",
  "manufacturer": "MPB Communications",
  "description": "这是一台由MPB Communications生产的连续波激光器，可提供稳定的连续激光输出。实验中常用于荧光激发、光学对准、显微成像以及其他需要可调激光功率的光学测量任务。",
  "description_en": "This is a continuous-wave laser made by MPB Communications, providing stable continuous laser output. In laboratories, it is commonly used for fluorescence excitation, optical alignment, microscopy, and other optical measurements that require adjustable laser power.",
  "tag_hints": [
    "continuous-wave laser",
    "laser power control",
    "fluorescence excitation",
    "optical alignment",
    "microscopy",
    "serial communication"
  ],
  "actions": [
    {
      "action_name": "auto-query",
      "description": "向激光器发送串口命令并读取返回信息。",
      "description_en": "Send a serial command to the laser and read back its response."
    },
    {
      "action_name": "auto-IsOn",
      "description": "获取激光器是否处于开启/初始化完成状态。",
      "description_en": "Get whether the laser is on / initialized."
    },
    {
      "action_name": "auto-check_on",
      "description": "检查激光器是否已开启。",
      "description_en": "Check whether the laser is turned on."
    },
    {
      "action_name": "auto-TurnOn",
      "description": "打开激光器输出。",
      "description_en": "Turn on the laser output."
    },
    {
      "action_name": "auto-TurnOff",
      "description": "关闭激光器输出。",
      "description_en": "Turn off the laser output."
    },
    {
      "action_name": "auto-SetPower",
      "description": "设定激光器输出功率。",
      "description_en": "Set the laser output power."
    },
    {
      "action_name": "auto-GetPower",
      "description": "获取激光器设定功率。",
      "description_en": "Get the configured laser power setpoint."
    },
    {
      "action_name": "auto-GetRealPower",
      "description": "获取激光器实际输出功率。",
      "description_en": "Get the actual laser output power."
    },
    {
      "action_name": "auto-Close",
      "description": "关闭与激光器的通信连接。",
      "description_en": "Close the communication connection to the laser."
    }
  ]
}

